import string

VOWELS = 'aeiou'

def has_player_won(secret_word, letters_guessed):
    for letter in secret_word:
        if letter not in letters_guessed:
            return False
    return True

def get_word_progress(secret_word, letters_guessed):
    progress = ''
    for letter in secret_word:
        progress += letter if letter in letters_guessed else '*'
    return progress

def get_available_letters(letters_guessed):
    available = ''
    for letter in string.ascii_lowercase:
        if letter not in letters_guessed:
            available += letter
    return available

def hangman(secret_word, with_help):
    print('Welcome to Hangman!')
    print('I am thinking of a word that is', len(secret_word), 'letters long.')
    guesses_remaining = 10
    letters_guessed = []
    while guesses_remaining > 0 and not has_player_won(secret_word, letters_guessed):
        print('------')
        print('You have', guesses_remaining, 'guesses left.')
        print('Available letters:', get_available_letters(letters_guessed))
        guess = input('Please guess a letter: ')
        if len(guess) != 1 or (guess not in string.ascii_lowercase and not (with_help and guess == '!')):
            print('Oops! That is not a valid single lowercase letter:', get_word_progress(secret_word, letters_guessed))
            continue
        if with_help and guess == '!':
            if guesses_remaining < 3:
                print('Oops! You do not have enough guesses left to use a hint.')
                continue
            missing = [c for c in secret_word if c not in letters_guessed]
            reveal = sorted(set(missing))[0]
            letters_guessed.append(reveal)
            guesses_remaining -= 3
            print('Letter revealed:', reveal)
            print(get_word_progress(secret_word, letters_guessed))
            continue
        if guess in letters_guessed:
            print('Oops! You have already guessed that letter:', get_word_progress(secret_word, letters_guessed))
            continue
        letters_guessed.append(guess)
        if guess in secret_word:
            print('Good guess:', get_word_progress(secret_word, letters_guessed))
        else:
            penalty = 2 if guess in VOWELS else 1
            guesses_remaining -= penalty
            print('Oops! That letter is not in my word:', get_word_progress(secret_word, letters_guessed))
    print('------')
    if has_player_won(secret_word, letters_guessed):
        score = (guesses_remaining + 4 * len(set(secret_word))) + (3 * len(secret_word))
        print('Congratulations, you won!')
        print('Your total score for this game is:', score)
    else:
        print('Sorry, you ran out of guesses. The word was', secret_word)
